#!/usr/bin/env python3
"""Send only disabled STOP, require fresh ACK generated by the chassis."""
import argparse
import fcntl
import json
import os
import secrets
import select
import termios
import time
import tty
from pathlib import Path
from check_port import check
from usb_protocol import Stream, command


def run(port, duration=5, report_path=None):
    if not 1 <= duration <= 60:
        raise ValueError('测试时长须为 1～60 秒')
    port = check(port)
    fd = os.open(port, os.O_RDWR | os.O_NOCTTY | os.O_NONBLOCK)
    exclusive = False
    stream = Stream()
    report = {'port': port, 'enabled': False, 'passed': False}
    try:
        fcntl.flock(fd, fcntl.LOCK_EX | fcntl.LOCK_NB)
        fcntl.ioctl(fd, termios.TIOCEXCL)
        exclusive = True
        tty.setraw(fd)
        attrs = termios.tcgetattr(fd)
        attrs[4] = attrs[5] = termios.B115200
        termios.tcsetattr(fd, termios.TCSANOW, attrs)
        termios.tcflush(fd, termios.TCIOFLUSH)
        session = secrets.randbelow(0xffffffff) + 1
        report['session'] = session
        sent = {}; sequence = 0; count = 0; last_uptime = None; last_ack = None
        start = time.monotonic(); next_send = start
        while time.monotonic() - start < duration:
            now = time.monotonic()
            if now >= next_send:
                frame = command(session, sequence, int((now-start)*1000))
                offset = 0
                while offset < len(frame):
                    _, writable, _ = select.select([], [fd], [], .05)
                    if not writable:
                        raise RuntimeError('USB 写入超时')
                    offset += os.write(fd, frame[offset:])
                sent[sequence] = now; sequence = (sequence+1) & 65535
                sent = {seq:t for seq,t in sent.items() if now-t < .25}
                next_send = now + .02
            readable, _, _ = select.select([fd], [], [], .005)
            if not readable:
                continue
            data = os.read(fd,4096)
            if not data:
                raise RuntimeError('USB 已断开')
            for f in stream.push(data):
                if f['session'] != session or not f['status'] & 64 or f['sequence'] not in sent:
                    continue
                if f['status'] & 2:
                    raise RuntimeError('STOP 测试收到 ACTIVE 状态')
                if last_uptime is not None and not 0 < ((f['uptime']-last_uptime)&0xffffffff) < 0x80000000:
                    continue
                last_uptime = f['uptime']; last_ack = time.monotonic(); count += 1
                print(json.dumps(f, ensure_ascii=False), flush=True)
        report.update(sent_STOP=sequence, fresh_chassis_ACK=count)
        if count < 10 or last_ack is None or time.monotonic()-last_ack > .25:
            raise RuntimeError(f'未获得持续的新鲜底盘 STOP ACK（有效 {count} 帧）')
        report['passed'] = True
        print(f'PASS: {count} 帧新鲜底盘 STOP ACK；全程 ENABLE=0。fault 位含义见文档。')
    except (OSError, ValueError, RuntimeError) as exc:
        report['error'] = str(exc)
        raise
    finally:
        report.update(USB_bytes=stream.bytes_received, frames=stream.frames,
                      last_gimbal=stream.last_gimbal)
        joint = stream.last_gimbal
        if not report['passed']:
            if stream.frames['feedback']:
                diagnosis = '收到有效底盘反馈，但会话、ACK 标记、序号、新鲜度或 STOP 状态未通过验收。'
            elif joint and joint['session'] == report.get('session'):
                diagnosis = '云台已解析本轮 USB 命令；底盘 CAN 回复未通过验收，需检查 CAN 状态和底盘固件。'
            elif stream.frames['SP']:
                diagnosis = 'USB 有云台遥测，但尚未确认云台解析本轮导航命令。'
            elif stream.bytes_received:
                diagnosis = 'USB 有字节，但未解析到有效云台遥测或底盘反馈，需检查固件协议。'
            else:
                diagnosis = 'USB 没有收到字节，需检查板内程序是否运行以及 USB 数据链路。'
            report['diagnosis'] = diagnosis
            print('诊断：' + diagnosis, flush=True)
        print('链路统计：' + json.dumps(report, ensure_ascii=False), flush=True)
        if exclusive:
            try:
                fcntl.ioctl(fd, termios.TIOCNXCL)
            except OSError:
                pass
        os.close(fd)
        if report_path:
            path = Path(report_path)
            path.parent.mkdir(parents=True, exist_ok=True)
            path.write_text(json.dumps(report, ensure_ascii=False, indent=2) + '\n')


if __name__ == '__main__':
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('port')
    parser.add_argument('--duration', type=float, default=5)
    parser.add_argument('--report', help='保存 JSON 诊断结果')
    args = parser.parse_args()
    try:
        run(args.port, args.duration, args.report)
    except (OSError, ValueError, RuntimeError) as exc:
        raise SystemExit('FAIL: ' + str(exc))
